// Filter distressed-property leads before skip tracing.
// Removes corporate / government / bank owners, zero-value parcels,
// standardizes addresses, and swaps to mailing address for absentee owners.
var items = $input.all();
var allLeads = [];
for (var i = 0; i < items.length; i++) { allLeads.push(items[i].json); }

if (allLeads.length === 0) {
  return [{ json: { hasLeads: false, leadsCount: 0, filteredOut: 0, reason: 'No pending leads in Convex', jsonData: null, parcelIds: [] } }];
}

var corporatePattern = /\b(LLC|INC|INCORPORATED|CORP|CORPORATION|LP|LTD|LIMITED|TRUST|REVOCABLE|IRREVOCABLE|ESTATE|ESTATES|PARTNERSHIP|HOLDING|HOLDINGS|PROPERTIES|PROPERTY|INVESTMENTS|INVEST|MANAGEMENT|REALTY|CAPITAL|VENTURES|FUND|GROUP|ASSOCIATES|PARTNERS|COMPANY|CO\.|BANK|ENTERPRISES|DEVELOPMENT|RENTALS|ASSET|ASSETS|EQUITY|FINANCIAL|SERVICES|SOLUTIONS|ACQUISITION|CONSTRUCTION|CONTRACTING|FOUNDATION|PLUMBING|ELECTRIC|ROOFING|HVAC|RESTORATION|BUILDERS|CHURCH)\b/i;
var governmentPattern = /\b(CITY OF|STATE OF|COUNTY|LAND BANK|HUD|HOUSING AUTHORITY|REDEVELOPMENT|MUNICIPAL|TOWNSHIP|VILLAGE OF|BOARD OF|DEPARTMENT|AGENCY|COMMISSION|AUTHORITY|GOVERNMENT|PUBLIC|FEDERAL|METRO|DISTRICT)\b/i;
var bankPattern = /\b(FANNIE MAE|FREDDIE MAC|MORTGAGE CO|WELLS FARGO|JPMORGAN|CHASE BANK|BANK OF AMERICA|CITIBANK|US BANK|NATIONSTAR|OCWEN|CARRINGTON|CENLAR|LOANCARE|PHH MORTGAGE|SHELLPOINT|NEWREZ|FLAGSTAR)\b/i;

function standardizeAddress(addr) {
  if (!addr) return '';
  var s = addr.toUpperCase().trim();
  s = s.replace(/\bNORTH\b/g, 'N').replace(/\bSOUTH\b/g, 'S').replace(/\bEAST\b/g, 'E').replace(/\bWEST\b/g, 'W');
  s = s.replace(/\bSTREET\b/g, 'ST').replace(/\bAVENUE\b/g, 'AVE').replace(/\bBOULEVARD\b/g, 'BLVD').replace(/\bDRIVE\b/g, 'DR').replace(/\bROAD\b/g, 'RD').replace(/\bLANE\b/g, 'LN').replace(/\bCOURT\b/g, 'CT');
  s = s.replace(/(\d+)(ST|ND|RD|TH)\b/g, '$1');
  s = s.replace(/\s+/g, ' ').trim();
  s = s.replace(/\s*(APT|UNIT|STE|SUITE|#)\s*\S*$/i, '');
  return s;
}

var filteredLeads = [], parcelIds = [], rejectedLeads = [];
for (var i = 0; i < allLeads.length; i++) {
  var item = allLeads[i];
  var prop = item.property || item;
  var owner = (prop.ownerName || '').trim();
  if (corporatePattern.test(owner)) { rejectedLeads.push({ owner: owner, reason: 'corporate' }); continue; }
  if (governmentPattern.test(owner)) { rejectedLeads.push({ owner: owner, reason: 'government' }); continue; }
  if (bankPattern.test(owner)) { rejectedLeads.push({ owner: owner, reason: 'bank' }); continue; }
  if (!prop.totalValue || prop.totalValue === 0) { rejectedLeads.push({ owner: owner, reason: 'zero_value' }); continue; }

  var firstName = '', lastName = '';
  var ownerUpper = owner.toUpperCase();
  if (ownerUpper.indexOf(',') !== -1) {
    var np = ownerUpper.split(',');
    lastName = np[0].trim();
    firstName = (np[1] || '').trim().split(/\s+/)[0] || '';
  } else {
    var parts = ownerUpper.split(/\s+/);
    firstName = parts[0] || '';
    lastName = parts.slice(1).join(' ') || '';
  }
  lastName = lastName.replace(/\s*ET\s+AL\s*/i, '').trim();
  firstName = firstName.replace(/\s*&.*$/i, '').trim();

  var isAbsentee = prop.isAbsentee || false;
  var hasMail = prop.mailAddress && prop.mailAddress.length > 2;
  var addrParts = (prop.address || '').split(',');
  var propStreet = (addrParts[0] || '').trim();
  var propCity = prop.city || (addrParts[1] || '').trim();
  var propState = prop.state || 'OH';
  var propZip = prop.zip || (addrParts[3] || '').trim();

  var primaryAddr = (isAbsentee && hasMail) ? prop.mailAddress : propStreet;
  var primaryCity = (isAbsentee && hasMail) ? (prop.mailCity || propCity) : propCity;
  var primaryState = (isAbsentee && hasMail) ? (prop.mailState || propState) : propState;
  var primaryZip = (isAbsentee && hasMail) ? (prop.mailZip || propZip) : propZip;

  filteredLeads.push({
    address: standardizeAddress(primaryAddr),
    city: primaryCity.toUpperCase().trim(),
    state: primaryState.toUpperCase().trim(),
    zip: (primaryZip || '').toString().trim().substring(0,5),
    first_name: firstName, last_name: lastName,
    mail_address: standardizeAddress(propStreet),
    mail_city: propCity.toUpperCase().trim(),
    mail_state: propState.toUpperCase().trim(),
    mail_zip: (propZip || '').toString().trim().substring(0,5)
  });
  parcelIds.push(prop.parcelId);
}

return [{ json: {
  hasLeads: filteredLeads.length > 0,
  leadsCount: filteredLeads.length,
  filteredOut: rejectedLeads.length,
  totalFromConvex: allLeads.length,
  rejectedLeads: rejectedLeads,
  jsonData: filteredLeads,
  parcelIds: parcelIds
} }];

var tracerfyResponse = $('Upload to Tracerfy').first().json;
var filterData = $('Filter & Format Leads').first().json;
var jobId = tracerfyResponse.queue_id || tracerfyResponse.job_id || tracerfyResponse.id || 'unknown';
return [{ json: {
  status: 'submitted',
  jobId: jobId,
  leadsUploaded: filterData.leadsCount,
  leadsFiltered: filterData.filteredOut,
  totalFromConvex: filterData.totalFromConvex,
  parcelIdsMarked: filterData.parcelIds.length,
  cost: '$' + (filterData.leadsCount * 0.02).toFixed(2),
  rejectedLeads: filterData.rejectedLeads,
  note: 'Skip Trace Results Router will process phone numbers when ready'
} }];

var filterData = $('Filter & Format Leads').first().json;
return [{ json: {
  status: 'no_leads',
  reason: filterData.reason || 'All leads filtered out (corporate/govt/bank)',
  totalFromConvex: filterData.totalFromConvex || 0,
  filteredOut: filterData.filteredOut || 0,
  rejectedLeads: filterData.rejectedLeads || []
} }];
